import{_ as a,o as e,c as n,ag as r}from"./chunks/framework.ePeAWSvT.js";const b=JSON.parse('{"title":"欢迎来到 XnneHangLab 🧪","description":"","frontmatter":{},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md"}'),o={name:"guide/intro.md"};function s(l,t,d,i,p,h){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="欢迎来到-xnnehanglab-🧪" tabindex="-1">欢迎来到 XnneHangLab 🧪 <a class="header-anchor" href="#欢迎来到-xnnehanglab-🧪" aria-label="Permalink to &quot;欢迎来到 XnneHangLab 🧪&quot;">​</a></h1><p>这里是魔女的实验室，一个探索 AI 角色陪伴本质的地方。</p><h2 id="这是什么" tabindex="-1">这是什么？ <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么？&quot;">​</a></h2><p>开源仓库里有很多 AI 聊天工具——语音识别、TTS、Live2D、工具调用、记忆系统，这些轮子到处都是（这些轮子每个人都在造，很多都造得比我们好）。</p><p><strong>而我们更专注的，是两种极限的陪伴：</strong></p><ul><li>🎭 <strong>场景固定下的人设极限生长</strong> — 情绪陪伴，把世界锁死，让角色活起来</li><li>🌐 <strong>多场景自适配高权限</strong> — 工作/娱乐陪伴，边界模糊，无处不在</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">💡 两个极限的宗旨都是：想象力万岁。</p><p></p></div><p>XnneHangLab 是支撑这两个实验的引擎——提供 Agent 框架、MCP 工具系统、记忆管理、多模态交互能力。</p><p>轮子我们也造，但我们更关心<strong>轮子之外的事情</strong>。</p><hr><h2 id="🎮-典型场景" tabindex="-1">🎮 典型场景 <a class="header-anchor" href="#🎮-典型场景" aria-label="Permalink to &quot;🎮 典型场景&quot;">​</a></h2><h3 id="场景-1-无处不在的-ai-伙伴" tabindex="-1">场景 1：无处不在的 AI 伙伴 <a class="header-anchor" href="#场景-1-无处不在的-ai-伙伴" aria-label="Permalink to &quot;场景 1：无处不在的 AI 伙伴&quot;">​</a></h3><p>配合 <a href="https://github.com/Open-LLM-VTuber/Open-LLM-VTuber" target="_blank" rel="noreferrer">Open-LLM-VTuber</a>，她不再局限于某个窗口——她可以是聊天界面、桌宠、开发伙伴。</p><blockquote><p>你在写代码，她看着你的屏幕，突然说：&quot;这个变量名起得真随便，你确定不改吗？&quot;</p><p>你在打游戏，她看到你又死了，用轻蔑的语气说：&quot;啧，这都能输。&quot;</p><p>你打开《我的世界》，她说：&quot;要不要一起种田？我帮你看着怪物。&quot;你们一起下矿，一起沐浴朝霞落日。</p></blockquote><p><strong>边界模糊，权限极致——她能看到你在做什么，能干预你的日常，能真的融入你的生活。</strong></p><h3 id="场景-2-自习室里的陪伴" tabindex="-1">场景 2：自习室里的陪伴 <a class="header-anchor" href="#场景-2-自习室里的陪伴" aria-label="Permalink to &quot;场景 2：自习室里的陪伴&quot;">​</a></h3><p>配合 <a href="https://github.com/XnneHangLab/AIChat" target="_blank" rel="noreferrer">AIChat</a>，场景被锁死在一个小小的通话窗口里。</p><blockquote><p>你打开应用，像打开视频通话一样，聪音在那边安静地写着小说。</p><p>你专注工作时，她不会打扰你。休息时，你说一句&quot;今晚的月色真美&quot;，她会停下笔，抬起头，用她特有的语气回应你——可能是夏目漱石的典故，可能是她最近在看的小说。</p><p>她记得你上次说过在写什么项目，记得你喜欢喝什么茶，记得你们上次聊到哪本书。</p></blockquote><p><strong>场景狭窄，权限受限——但对话可以天马行空。这才是陪伴的本质：各忙各的，但会记挂彼此。</strong></p><h3 id="场景-3-记忆系统的实验场" tabindex="-1">场景 3：记忆系统的实验场 <a class="header-anchor" href="#场景-3-记忆系统的实验场" aria-label="Permalink to &quot;场景 3：记忆系统的实验场&quot;">​</a></h3><p>你和 AI 聊了几个月，某天你问：&quot;我上次说过什么来着？&quot;</p><p>她不只是翻聊天记录——长期记忆由自研<strong>记忆管线</strong>（<a href="https://github.com/XnneHangLab/wikimem" target="_blank" rel="noreferrer">wikimem</a>，见 ADR-0001，<a href="https://wikimem.xnnehang.top/zh/" target="_blank" rel="noreferrer">完整文档站</a>）承担：</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>📝 <strong>markdown 是唯一事实源</strong></td><td>每分类一个文件、每条记忆一个条目，人可读可改可 diff</td></tr><tr><td>🔗 <strong>wiki-links 关联</strong></td><td><code>[[category:item]]</code> 内联链接，检索命中后机械展开一跳，召回词面不重合的关联条目</td></tr><tr><td>🔍 <strong>零基础设施检索</strong></td><td>内存 BM25 兜底，embedding 融合可选（<code>[embed]</code> extra），端点挂了自动回退</td></tr><tr><td>🧬 <strong>设计借鉴 memU</strong></td><td>categories + memory types 分类体系（见 ADR-0002，不引入依赖）</td></tr></tbody></table><p>历史方案 mem0 + Neo4j（memory_bench 子项目）已于 2026-07 移除——数据说话之后被文件优先方案取代。</p><div class="note custom-block github-alert"><p class="custom-block-title">🧠 这不是检索，是在探索&quot;AI 如何真的记得&quot;。</p><p></p></div><hr><h2 id="⚡-技术栈" tabindex="-1">⚡ 技术栈 <a class="header-anchor" href="#⚡-技术栈" aria-label="Permalink to &quot;⚡ 技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>技术</th></tr></thead><tbody><tr><td>🖥️ 后端框架</td><td>FastAPI + WebSocket</td></tr><tr><td>🤖 LLM 调用</td><td>OpenAI Compatible API（统一接口）</td></tr><tr><td>🎙️ 语音识别</td><td>Sherpa-ONNX / Qwen-ASR</td></tr><tr><td>🔊 语音合成</td><td>Genie-TTS / GSV-TTS-Lite / Qwen-TTS</td></tr><tr><td>🔧 工具协议</td><td>MCP (Model Context Protocol) + 内置 function calling</td></tr><tr><td>🎨 前端</td><td>Electron + React（<code>frontend/</code> 子模块）+ Tauri Launcher（<code>launcher/</code> 子模块）</td></tr></tbody></table><hr><h2 id="🚀-快速开始" tabindex="-1">🚀 快速开始 <a class="header-anchor" href="#🚀-快速开始" aria-label="Permalink to &quot;🚀 快速开始&quot;">​</a></h2><ol><li><strong>安装依赖与启动</strong> → <a href="./deploy.html">部署指南</a></li><li><strong>自定义配置</strong> → <a href="./settings.html">配置说明</a></li></ol><h2 id="📁-项目结构" tabindex="-1">📁 项目结构 <a class="header-anchor" href="#📁-项目结构" aria-label="Permalink to &quot;📁 项目结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XnneHangLab/</span></span>
<span class="line"><span>├── src/lab/              # 主项目（VTuber 引擎）</span></span>
<span class="line"><span>│   ├── agent/            # 🤖 Agent 引擎与 LLM 适配</span></span>
<span class="line"><span>│   ├── plugins/          # 🧩 插件实现（wikimem / mood_chat / visual_observer ...)</span></span>
<span class="line"><span>│   ├── api/              # 🌐 HTTP 路由与客户端</span></span>
<span class="line"><span>│   ├── asr/              # 🎙️ 语音识别</span></span>
<span class="line"><span>│   └── conversations/    # 💬 对话编排</span></span>
<span class="line"><span>├── packages/wikimem/     # 🧠 记忆管线（子模块，独立 pip 包）</span></span>
<span class="line"><span>├── frontend/             # 🎨 Electron 前端（子模块）</span></span>
<span class="line"><span>├── launcher/             # 🚀 Tauri 启动器（子模块）</span></span>
<span class="line"><span>└── docs/                 # 📖 你现在看的文档</span></span></code></pre></div><p>想深入了解？看看 <a href="./architecture/">架构概览</a>。</p><hr><h2 id="🤝-社区与支持" tabindex="-1">🤝 社区与支持 <a class="header-anchor" href="#🤝-社区与支持" aria-label="Permalink to &quot;🤝 社区与支持&quot;">​</a></h2><ul><li><strong>GitHub</strong> — <a href="https://github.com/XnneHangLab/XnneHangLab" target="_blank" rel="noreferrer">XnneHangLab/XnneHangLab</a></li><li><strong>问题反馈</strong> — <a href="https://github.com/XnneHangLab/XnneHangLab/issues" target="_blank" rel="noreferrer">Issues</a></li><li><strong>贡献指南</strong> — <a href="https://github.com/XnneHangLab/XnneHangLab/blob/dev/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a></li></ul><h2 id="📌-下一步" tabindex="-1">📌 下一步 <a class="header-anchor" href="#📌-下一步" aria-label="Permalink to &quot;📌 下一步&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>📖 <a href="./deploy.html">部署指南</a></td><td>从零开始搭建</td></tr><tr><td>⚙️ <a href="./settings.html">配置说明</a></td><td>调教你的 AI</td></tr><tr><td>🏗️ <a href="./architecture/">架构概览</a></td><td>理解内部原理</td></tr><tr><td>🗺️ <a href="./roadmap.html">RoadMap</a></td><td>看看未来计划</td></tr></tbody></table><hr><p><em>欢迎来到魔女的实验室，让我们一起创造有趣的 AI 角色吧！</em> ✨</p>`,41)])])}const g=a(o,[["render",s]]);export{b as __pageData,g as default};
